function serviceInfo(code){
 const s=getService(code);if(!s)return;
 const sla=s.sla||slaProfiles().find(x=>(x.code||x.tier)===s.tier)||{};
 const rateRows=s.price?.rows||[];
 const terms=Array.isArray(s.terms)?s.terms:Object.entries(s.terms||{}).map(([label,value])=>({label,value}));
 const body='<p class="muted-copy">'+esc(s.description||s.name)+'</p><div class="service-info-meta"><span class="tag blue">'+esc(s.code)+'</span><span class="tag blue">'+esc(s.centerName)+'</span><span class="tag muted">'+esc(s.zone)+'</span></div><div class="summary-box"><h4>مدل درآمدی و ارائه</h4><div class="summary-list"><div><span>مدل محاسبه</span><b>'+esc(modelLabels[s.model]||'نامشخص')+'</b></div><div><span>واحد مصرف</span><b>'+esc(s.unit||'در منبع تعیین نشده')+'</b></div><div><span>روش ارائه</span><b>'+esc(deliveryLabels[s.delivery]||'نامشخص')+'</b></div><div><span>SLA منبع</span><b>'+esc(s.tier||'نامشخص')+'</b></div></div></div>'+
 (rateRows.length?'<h3 class="section-caption">نرخ‌نامه مشاهده‌شده</h3><div class="data-table-wrap"><table class="data-table rate-table"><thead><tr><th>شرح</th><th>واحد</th><th>مبلغ در منبع</th></tr></thead><tbody>'+rateRows.map(r=>'<tr><td>'+esc(r.label)+'</td><td>'+esc(r.unit||'—')+'</td><td>'+esc(r.amountText||r.amountIrr||'—')+'</td></tr>').join('')+'</tbody></table></div>':'')+
 (s.price?.rawText?'<details class="source-excerpt"><summary>متن شرایط و نرخ‌نامه منبع</summary><pre>'+esc(s.price.rawText)+'</pre></details>':'')+
 (terms.length?'<h3 class="section-caption">شرایط سرویس</h3><dl class="integration-meta">'+terms.map(t=>'<dt>'+esc(t.label)+'</dt><dd>'+esc(t.value)+'</dd>').join('')+'</dl>':'')+
 '<div class="summary-box"><h4>تعهدات سطح خدمت</h4><div class="summary-list"><div><span>دسترس‌پذیری</span><b>'+esc(sla.availability||(sla.availabilityPct?String(sla.availabilityPct)+'%':'نامشخص'))+'</b></div><div><span>پاسخ</span><b>'+esc(sla.response||'نامشخص')+'</b></div><div><span>هدف رفع</span><b>'+esc(sla.resolution||sla.resolutionTarget||'نامشخص')+'</b></div><div><span>پوشش</span><b>'+esc(sla.coverage||'نامشخص')+'</b></div></div></div><div class="source-proof"><strong>ردیابی منبع</strong><a href="'+esc(s.sourceUrl||state.data.catalog.source||'https://fanasa.net/fa/products')+'" target="_blank" rel="noopener">مشاهده صفحه رسمی ↗</a><small>'+dateText(s.observedAt||state.data.catalog.observedAt)+' · '+esc(s.verificationStatus||state.data.catalog.verificationStatus)+'</small>'+(s.sourceHash?'<code dir="ltr">'+esc(s.sourceHash)+'</code>':'')+'</div>';
 showModal(s.name,body,action('close-modal','بستن')+action('service-select-toggle',state.selected.has(code)?'حذف از انتخاب':'افزودن به انتخاب','primary','data-id="'+esc(code)+'"'),true);
}

function customersView(){const cs=list('customers');return header('مشتریان هلدینگی','ساختار هلدینگ، شرکت‌های تابع و مدیر حساب هر رابطه را مدیریت کنید.',action('new-customer','＋ مشتری جدید','primary'))+
 '<div class="crm-stats"><span><b>'+nf(cs.filter(c=>!c.parentId).length)+'</b> هلدینگ / مشتری مستقل</span><span><b>'+nf(cs.filter(c=>c.parentId).length)+'</b> شرکت تابع</span><span><b>'+nf(cs.filter(c=>c.managerId).length)+'</b> مشتری با مدیر حساب</span></div><section class="card"><div class="card-header"><h2>دفتر مشتریان</h2><label class="filter-search"><span>⌕</span><input data-search="customers" placeholder="نام مشتری، واحد یا مدیر…" aria-label="جست‌وجوی مشتری"></label></div>'+
 (cs.length?'<div class="data-table-wrap"><table class="data-table"><thead><tr><th>مشتری</th><th>هلدینگ مادر</th><th>واحد / صنعت</th><th>مدیر حساب</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>'+cs.map(c=>'<tr data-search-row><td><strong>'+esc(c.name)+'</strong><small class="table-sub">'+esc(c.id.slice(0,8))+'</small></td><td>'+esc(getCustomer(c.parentId)?.name||'مشتری مستقل')+'</td><td>'+esc(c.unit||'—')+'<small class="table-sub">'+esc(c.industry||'—')+'</small></td><td>'+esc(getManager(c.managerId)?.name||'تخصیص داده نشده')+'</td><td>'+chip(c.status)+'</td><td><button class="table-action" data-action="edit-customer" data-id="'+esc(c.id)+'" aria-label="ویرایش '+esc(c.name)+'">✎</button><button class="table-action danger-text" data-action="delete-customer" data-id="'+esc(c.id)+'" aria-label="حذف '+esc(c.name)+'">×</button></td></tr>').join('')+'</tbody></table></div>':empty('مشتری تعریف نشده','ابتدا هلدینگ یا یک شرکت مستقل را اضافه کنید.'))+'</section>';}
function managersView(){const ms=list('managers');return header('اکانت منیجرها','مدیران حساب، مسئول رابطه با مشتری هستند؛ دسترسی کاربری در این نسخه وجود ندارد.',action('new-manager','＋ مدیر حساب جدید','primary'))+(ms.length?'<div class="manager-grid">'+ms.map((m,i)=>{const cs=list('customers').filter(c=>c.managerId===m.id);return '<article class="card manager-card"><div class="manager-head"><span class="manager-avatar tone-'+i%3+'">'+esc(m.name[0])+'</span><div><h3>'+esc(m.name)+'</h3><small>'+esc(m.role||'مدیر حساب')+'</small></div>'+chip(m.status||'active')+'</div><dl class="manager-contact"><dt>ایمیل</dt><dd dir="ltr">'+esc(m.email||'—')+'</dd><dt>تلفن</dt><dd dir="ltr">'+esc(m.phone||'—')+'</dd></dl><div class="manager-portfolio"><strong>'+nf(cs.length)+' مشتری در پرتفوی</strong><div>'+cs.map(c=>'<span class="tag blue">'+esc(c.name)+'</span>').join('')+(cs.length?'':'<small>هنوز مشتری تخصیص داده نشده</small>')+'</div></div><div class="manager-actions">'+action('manager-assign','تخصیص مشتری','secondary','data-id="'+esc(m.id)+'"')+action('edit-manager','ویرایش','ghost','data-id="'+esc(m.id)+'"')+'<button class="table-action danger-text" data-action="delete-manager" data-id="'+esc(m.id)+'" aria-label="حذف '+esc(m.name)+'">×</button></div></article>';}).join('')+'</div>':empty('مدیر حسابی تعریف نشده','مدیر حساب را اضافه و سپس به مشتری متصل کنید.'));}
function entityEditor(type,id){const isCustomer=type==='customer';const data=id?(isCustomer?getCustomer(id):getManager(id)):{};state.editor={type,id};const body='<form id="entityForm" class="form-grid">'+field((isCustomer?'نام مشتری':'نام و نام خانوادگی')+' <span class="required">*</span>',input('name',data.name,'required maxlength="200" autocomplete="off"'),true)+
 (isCustomer?field('هلدینگ مادر',select('parentId',list('customers').filter(x=>x.id!==id).map(x=>({value:x.id,label:x.name})),data.parentId,'مشتری مستقل'))+field('مدیر حساب',select('managerId',list('managers').filter(x=>x.status!=='inactive').map(x=>({value:x.id,label:x.name})),data.managerId,'بدون تخصیص'))+field('واحد بهره‌بردار',input('unit',data.unit,'maxlength="150"'))+field('حوزه فعالیت',input('industry',data.industry,'maxlength="150"')):field('سمت',input('role',data.role||'مدیر حساب','maxlength="150"'))+field('ایمیل',input('email',data.email,'type="email" dir="ltr" maxlength="254"'))+field('تلفن',input('phone',data.phone,'type="tel" dir="ltr" maxlength="40"')))+field('وضعیت',select('status',(isCustomer?['active','lead','paused','churned']:['active','inactive']).map(x=>({value:x,label:statusLabels[x]})),data.status||'active'))+'</form>';showModal((id?'ویرایش ':'افزودن ')+(isCustomer?'مشتری':'مدیر حساب'),body,action('close-modal','انصراف')+action('save-entity','ذخیره اطلاعات','primary'));}
async function saveEntity(){const values=formValues('#entityForm');if(!values)return;if(!values.name.trim())throw new Error('نام را وارد کنید.');const {type,id}=state.editor;const path=type==='customer'?'/customers':'/managers';if(type==='customer'){values.parentId=values.parentId||null;values.managerId=values.managerId||null;}await busyRequest(()=>api(path+(id?'/'+encodeURIComponent(id):''),values,id?'PUT':'POST'));closeModal();await refresh();toast('اطلاعات ذخیره شد.');}
function confirmDelete(type,id){const item=type==='customer'?getCustomer(id):getManager(id);state.editor={type,id};showModal('حذف '+(type==='customer'?'مشتری':'مدیر حساب'),'<p class="confirm-text">رکورد «'+esc(item.name)+'» حذف شود؟ اگر این رکورد در قرارداد یا رابطه دیگری استفاده شده باشد، سرور حذف را نمی‌پذیرد.</p>',action('close-modal','انصراف')+action('confirm-delete','حذف رکورد','danger'));}
async function deleteEntity(){const {type,id}=state.editor;await busyRequest(()=>api('/'+(type==='customer'?'customers':'managers')+'/'+encodeURIComponent(id),undefined,'DELETE'));closeModal();await refresh();toast('رکورد حذف شد.');}
function assignmentEditor(id){const m=getManager(id);state.editor={type:'assignment',id};showModal('تخصیص مشتری به '+m.name,'<form id="assignmentForm"><p class="muted-copy">انتخاب مشتری، مدیر حساب آن رابطه را به این شخص تغییر می‌دهد.</p><div class="assignment-list">'+list('customers').map(c=>'<label><input type="checkbox" name="customer" value="'+esc(c.id)+'" '+(c.managerId===id?'checked':'')+'><span><strong>'+esc(c.name)+'</strong><small>مدیر فعلی: '+esc(getManager(c.managerId)?.name||'تخصیص داده نشده')+'</small></span></label>').join('')+'</div></form>',action('close-modal','انصراف')+action('save-assignment','ذخیره تخصیص','primary'));}
async function saveAssignment(){const id=state.editor.id;const selected=new Set(new FormData($('#assignmentForm')).getAll('customer'));const changes=list('customers').filter(c=>(selected.has(c.id)&&c.managerId!==id)||(!selected.has(c.id)&&c.managerId===id));await busyRequest(async()=>{for(const c of changes)await api('/customers/'+encodeURIComponent(c.id),{...c,managerId:selected.has(c.id)?id:null},'PUT');});closeModal();await refresh();toast('تخصیص مشتریان ذخیره شد.');}
function persistSelection(){try{sessionStorage.setItem('neocontract-selection',JSON.stringify([...state.selected]));}catch{}}
try{state.selected=new Set(JSON.parse(sessionStorage.getItem('neocontract-selection')||'[]'));}catch{}
async function busyRequest(work){if(state.busy)return;state.busy=true;const buttons=$$('button',modalRoot);buttons.forEach(b=>b.disabled=true);try{return await work();}finally{state.busy=false;buttons.forEach(b=>b.disabled=false);}}


function templatesView(){const q=state.templateSearch.toLowerCase();const ts=list('templates').filter(t=>(state.showArchived||t.status!=='archived')&&(!q||[t.title,t.category,t.description,t.code].join(' ').toLowerCase().includes(q)));return header('الگوهای قرارداد','متن، متغیرها و فرآیند مستقل؛ نسخه منتشرشده در قرارداد ثابت می‌ماند.',action('new-template','＋ الگوی جدید','primary'))+'<div class="template-toolbar"><label class="filter-search"><span>⌕</span><input data-search="templates" value="'+esc(state.templateSearch)+'" placeholder="عنوان یا دسته الگو…" aria-label="جست‌وجوی الگو"></label><label class="check-label"><input type="checkbox" data-show-archived '+(state.showArchived?'checked':'')+'> نمایش بایگانی</label><span>'+nf(ts.length)+' الگو</span></div>'+
 (ts.length?'<div class="card-grid">'+ts.map(t=>'<article class="card template-card"><div class="template-top"><span class="template-icon">▤</span>'+chip(t.status)+'</div><h3>'+esc(t.title)+'</h3><p>'+esc(t.description||t.category||'الگوی اختصاصی قرارداد')+'</p><div class="template-models">'+(t.revenueModels||[]).map(m=>'<span class="tag blue">'+esc(modelLabels[m]||m)+'</span>').join('')+'</div><div class="template-meta"><div><b>'+nf(t.version||1)+'</b><span>نسخه</span></div><div><b>'+nf((t.stages||[]).filter(s=>s.enabled!==false).length)+'</b><span>مرحله فعال</span></div><div><b>'+nf(list('contracts').filter(c=>c.templateId===t.id||c.snapshot?.template?.id===t.id).length)+'</b><span>قرارداد</span></div></div><div class="template-footer">'+action('edit-template',t.status==='published'?'نسخه جدید':'ویرایش','secondary','data-id="'+esc(t.id)+'"')+action('template-preview','مشاهده','ghost','data-id="'+esc(t.id)+'"')+'</div><div class="template-secondary-actions">'+((t.status==='published'||t.currentPublishedVersion)?action('use-template','استفاده از نسخه فعال','primary','data-id="'+esc(t.id)+'"'):'')+(t.status==='draft'?action('publish-template','انتشار نسخه','primary','data-id="'+esc(t.id)+'"'):'')+(t.status!=='archived'?'<button class="text-link muted" data-action="archive-template" data-id="'+esc(t.id)+'">بایگانی</button>':'')+'</div></article>').join('')+'</div>':empty('الگویی در این نما نیست','الگوی تازه ایجاد کنید یا فیلترها را تغییر دهید.'));}
const defaultStages = () => [{id:'legal',name:'بررسی حقوقی',role:'واحد حقوقی',slaDays:2,required:true,enabled:true},{id:'finance',name:'بررسی مالی',role:'واحد مالی',slaDays:2,required:true,enabled:true},{id:'management',name:'تأیید مدیریت',role:'مدیریت ارشد',slaDays:1,required:true,enabled:true},{id:'sign',name:'امضای مجاز',role:'صاحب امضا',slaDays:3,required:true,enabled:true}];
function stageEditor(stages,context,locked=false){return '<div class="stage-editor" data-stage-context="'+context+'">'+stages.map((s,i)=>'<div class="editable-stage '+(s.enabled===false?'disabled-stage':'')+'" data-stage-row="'+i+'"><span class="stage-number">'+nf(i+1)+'</span>'+field('نام مرحله',input('stageName',s.name,'required maxlength="150"'))+field('نقش مسئول',select('stageRole',[...Object.entries(roleLabels).map(([value,label])=>({value,label})),...(!roleLabels[s.role]?[{value:s.role,label:s.role}]:[])],s.role,undefined,'required '+(locked&&wizardTemplate()?.stages?.some(original=>original.id===s.id&&original.required)?'disabled':'')))+field('مهلت (روز)',input('stageDays',s.slaDays||1,'type="number" min="1" max="365" required'))+'<div class="stage-checks"><label><input type="checkbox" name="stageRequired" '+(s.required?'checked':'')+' '+(locked&&wizardTemplate()?.stages?.some(original=>original.id===s.id&&original.required)?'disabled':'')+'> الزامی</label><label><input type="checkbox" name="stageEnabled" '+(s.enabled!==false?'checked':'')+' '+(locked&&wizardTemplate()?.stages?.some(original=>original.id===s.id&&original.required)?'disabled':'')+'> فعال</label></div><div class="stage-controls"><button type="button" class="table-action" data-action="stage-up" data-context="'+context+'" data-index="'+i+'" aria-label="انتقال '+esc(s.name)+' به بالا" '+(i===0?'disabled':'')+'>↑</button><button type="button" class="table-action" data-action="stage-down" data-context="'+context+'" data-index="'+i+'" aria-label="انتقال '+esc(s.name)+' به پایین" '+(i===stages.length-1?'disabled':'')+'>↓</button><button type="button" class="table-action danger-text" data-action="stage-delete" data-context="'+context+'" data-index="'+i+'" aria-label="حذف '+esc(s.name)+'" '+(locked&&wizardTemplate()?.stages?.some(original=>original.id===s.id&&original.required)?'disabled':'')+'>×</button></div></div>').join('')+'</div><button type="button" class="btn btn-secondary btn-sm add-stage" data-action="stage-add" data-context="'+context+'">＋ افزودن مرحله</button><datalist id="roleOptions"><option value="واحد حقوقی"><option value="واحد مالی"><option value="مدیر حساب"><option value="واحد فنی"><option value="امنیت و انطباق"><option value="مدیریت ارشد"><option value="صاحب امضا"></datalist>';}
function collectStages(stages,context){$$('[data-stage-context="'+context+'"] [data-stage-row]').forEach(row=>{const s=stages[Number(row.dataset.stageRow)];s.name=$('[name="stageName"]',row).value.trim();s.role=$('[name="stageRole"]',row).value.trim();s.slaDays=Number($('[name="stageDays"]',row).value);s.required=$('[name="stageRequired"]',row).checked;s.enabled=s.required||$('[name="stageEnabled"]',row).checked;});return stages;}
function validateStages(stages){if(!stages.some(s=>s.enabled!==false))throw new Error('حداقل یک مرحله فعال لازم است.');if(stages.some(s=>!s.name.trim()||!s.role.trim()||!Number.isInteger(s.slaDays)||s.slaDays<1||s.slaDays>365))throw new Error('نام، نقش و مهلت ۱ تا ۳۶۵ روز را برای همه مراحل وارد کنید.');}
function editTemplate(id){const t=id?getTemplate(id):null;state.editor={type:'template',id,template:clone(t||{title:'',category:'خدمات',description:'',body:'موضوع قرارداد: {{title}}\n\nاین قرارداد میان ارائه‌دهنده خدمت و {{party}} از تاریخ {{start}} تا {{end}} منعقد می‌شود.\n\nخدمات قرارداد:\n{{services}}\n\nشرایط مالی:\nمبلغ قرارداد {{amount}} ریال است. {{paymentTerms}}\n\nتعهدات سطح خدمت:\n{{sla}}',revenueModels:[],stages:defaultStages(),serviceCodes:[]})};renderTemplateEditor();}
function renderTemplateEditor(){const t=state.editor.template;showModal(state.editor.id?(t.status==='published'?'ایجاد نسخه جدید از '+t.title:'ویرایش '+t.title):'ایجاد الگوی قرارداد','<form id="templateForm"><div class="form-grid">'+field('عنوان الگو <span class="required">*</span>',input('title',t.title,'required maxlength="200"'))+field('دسته‌بندی',input('category',t.category,'required maxlength="100"'))+field('شرح کاربرد',input('description',t.description,'maxlength="500"'),true)+field('بدنه الگو <span class="required">*</span>','<textarea name="body" class="contract-editor" rows="12" required>'+esc(t.body)+'</textarea>',true)+'</div><p class="editor-help">متغیرها: <code>{{title}} {{party}} {{customerName}} {{amount}} {{start}} {{end}} {{services}} {{sla}} {{paymentTerms}} {{unit}}</code></p><h3 class="section-caption">مدل‌های درآمدی مناسب</h3><div class="model-checks">'+Object.entries(modelLabels).map(([key,label])=>'<label><input type="checkbox" name="revenueModel" value="'+key+'" '+((t.revenueModels||[]).includes(key)?'checked':'')+'>'+label+'</label>').join('')+'</div><h3 class="section-caption">مراحل این الگو</h3>'+stageEditor(t.stages,'template')+'</form>',(t.status==='published'?'<span class="footer-note">ذخیره، یک نسخه پیش‌نویس جدید می‌سازد.</span>':'<span class="footer-note">پس از ذخیره، نسخه را منتشر کنید.</span>')+'<div class="page-actions">'+action('close-modal','انصراف')+action('save-template','ذخیره پیش‌نویس','primary')+'</div>',true);}
function syncTemplateEditor(){const f=$('#templateForm');const d=new FormData(f);Object.assign(state.editor.template,{title:d.get('title'),category:d.get('category'),description:d.get('description'),body:d.get('body'),revenueModels:d.getAll('revenueModel'),stages:collectStages(state.editor.template.stages,'template')});}
async function saveTemplate(){if(!$('#templateForm').reportValidity())return;syncTemplateEditor();const {id,template}=state.editor;validateStages(template.stages);try{await busyRequest(()=>api('/templates'+(id?'/'+encodeURIComponent(id):''),template,id?'PUT':'POST'));}catch(error){if(error.status===409){formError(error.message);const box=$('#modalError');box.insertAdjacentHTML('beforeend','<p>تغییرات این فرم حفظ شده‌اند. پیش از دریافت آخرین نسخه، متن مورد نیاز را کپی کنید.</p>'+action('reload-template','دریافت آخرین نسخه سرور','secondary','data-id="'+esc(id)+'"'));return;}throw error;}closeModal();await refresh();toast('پیش‌نویس الگو ذخیره شد؛ برای استفاده آن را منتشر کنید.');}
function templatePreview(id,versionId){const base=getTemplate(id);const t=(base.versions||[]).find(v=>v.templateVersionId===versionId)||base;const versions=base.versions||[];showModal(t.title+' · نسخه '+nf(t.version),'<div class="notice-note">متن الگوی دمو؛ متغیرها هنگام تولید قرارداد تکمیل می‌شوند.</div><pre class="document-paper">'+esc(t.body)+'</pre><h3 class="section-caption">فرآیند الگو</h3><div class="process-preview">'+(t.stages||[]).map((s,i)=>'<span class="'+(s.enabled===false?'off':'')+'"><b>'+nf(i+1)+'</b>'+esc(s.name)+'<small>'+esc(roleName(s.role))+' · '+nf(s.slaDays)+' روز'+(s.required?' · الزامی':'')+'</small></span>').join('')+'</div>'+(versions.length?'<h3 class="section-caption">تاریخچه نسخه‌ها</h3><div class="version-list">'+versions.map(v=>'<button class="version-option '+(v.templateVersionId===t.templateVersionId?'selected':'')+'" data-action="template-version" data-id="'+esc(id)+'" data-version="'+esc(v.templateVersionId)+'">نسخه '+nf(v.version||v.versionNo)+' '+chip(v.status)+'</button>').join('')+'</div>':''),action('close-modal','بستن')+(t.status==='published'?action('use-template','ساخت قرارداد از این نسخه','primary','data-id="'+esc(id)+'" data-version="'+esc(t.templateVersionId)+'"'):''),true);}
function processesView(){return header('فرآیندهای قرارداد','هر الگو مراحل خودش را دارد؛ هنگام ایجاد قرارداد یک نسخه مستقل از این مراحل ساخته می‌شود.')+'<div class="card-grid">'+publishedTemplates().map(t=>'<article class="card template-card"><div class="template-top"><span class="template-icon">◈</span><span class="tag blue">نسخه '+nf(t.version)+'</span></div><h3>'+esc(t.title)+'</h3><div class="process-list">'+(t.stages||[]).filter(s=>s.enabled!==false).map((s,i)=>'<div><span>'+nf(i+1)+'</span><p><strong>'+esc(s.name)+'</strong><small>'+esc(roleName(s.role))+' · '+nf(s.slaDays)+' روز'+(s.required?' · الزامی':'')+'</small></p></div>').join('')+'</div>'+action('edit-template','ویرایش در نسخه جدید','secondary','data-id="'+esc(t.id)+'"')+'</article>').join('')+'</div>';}
function manipulateStage(a,b){const context=b.dataset.context;let stages;if(context==='template'){syncTemplateEditor();stages=state.editor.template.stages;}else{collectWizard();stages=state.wizard.stages;}const i=Number(b.dataset.index);if(a==='stage-add')stages.push({id:uid(),name:'مرحله جدید',role:'مدیر حساب',slaDays:1,required:false,enabled:true});else if(a==='stage-delete'){if(context==='wizard'&&wizardTemplate()?.stages?.some(original=>original.id===stages[i].id&&original.required))return;stages.splice(i,1);}else{const j=a==='stage-up'?i-1:i+1;if(j>=0&&j<stages.length)[stages[i],stages[j]]=[stages[j],stages[i]];}if(context==='template')renderTemplateEditor();else renderWizard();}


function newWizard(templateId,templateVersionId){const base=getTemplate(templateId);const t=(base?.versions||[]).find(v=>v.templateVersionId===templateVersionId&&v.status==='published')||publishedTemplates().find(v=>v.id===templateId)||recommendedTemplate();if(!t){toast('ابتدا یک نسخه الگو را منتشر کنید.','warning');navigate('templates');return;}const today=new Date().toISOString().slice(0,10);state.wizard={step:1,idempotencyKey:crypto.randomUUID(),templateId:t.id,templateVersionId:t.templateVersionId,title:'',customerId:'',managerId:'',party:'',unit:'',owner:'مدیر قرارداد',amount:'',start:today,end:'',paymentTerms:'پرداخت طبق صورتحساب و شرایط توافق‌شده طرفین.',body:t.body,stages:clone(t.stages||defaultStages()),services:[...state.selected].map(getService).filter(Boolean).map(serviceTerms),preview:null};renderWizard();}
function serviceTerms(s){return {code:s.code,slaTier:s.tier||'',revenueModel:s.model||'',delivery:s.delivery||'',quantity:1,unitPrice:s.model==='included'?0:''};}
function wizardPayload(){const w=state.wizard;return {idempotencyKey:w.idempotencyKey,templateId:w.templateId,templateVersionId:w.templateVersionId,customerId:w.customerId,managerId:w.managerId||null,title:w.title.trim(),party:w.party.trim(),unit:w.unit,owner:w.owner,amount:Number(w.amount),start:w.start,end:w.end,paymentTerms:w.paymentTerms,body:w.body,services:w.services.map(x=>({...x,quantity:Number(x.quantity),unitPrice:x.unitPrice===''?null:Number(x.unitPrice)})),stages:clone(w.stages)};}
function renderWizard(){const w=state.wizard;const names=['انتخاب الگو','طرفین و زمان','خدمات و شرایط','فرآیند سفارشی','بازبینی سند'];const body='<div class="wizard-steps five-steps">'+names.map((n,i)=>'<div class="wizard-step '+(w.step===i+1?'active':'')+' '+(w.step>i+1?'done':'')+'"><span class="step-index">'+(w.step>i+1?'✓':nf(i+1))+'</span><span>'+n+'</span></div>').join('')+'</div><form id="wizardForm">'+wizardBody()+'</form>';const footer='<span class="footer-note">مرحله '+nf(w.step)+' از ۵ · نسخه مستقل هر قرارداد</span><div class="page-actions">'+action(w.step===1?'close-modal':'wizard-back',w.step===1?'انصراف':'بازگشت')+action(w.step===5?'wizard-create':'wizard-next',w.step===5?'ثبت پیش‌نویس قرارداد ✓':w.step===4?'تولید پیش‌نمایش سند ←':'ادامه ←','primary')+'</div>';showModal('ایجاد قرارداد جدید',body,footer,true);}
function versionPicker(){const w=state.wizard;const t=getTemplate(w.templateId);const versions=(t?.versions||[]).filter(v=>v.status==='published');return versions.length>1?'<div class="wizard-version-picker">'+field('نسخه منتشرشده مبنا',select('templateVersionId',versions.map(v=>({value:v.templateVersionId,label:'نسخه '+nf(v.version)+(v.templateVersionId===t.currentPublishedVersion?.templateVersionId?' · فعال':'' )})),w.templateVersionId,undefined,'data-wizard-version'))+'</div>':'';}
function wizardBody(){const w=state.wizard;const t=wizardTemplate();if(w.step===1)return '<h3 class="section-caption">الگوی مبنا را انتخاب کنید</h3><p class="muted-copy">انتخاب الگو، متن و مراحل اختصاصی همان نسخه را بارگذاری می‌کند.</p><div class="template-pick-grid">'+publishedTemplates().map(t=>'<button type="button" class="template-pick '+(t.id===w.templateId?'selected':'')+'" data-action="wizard-template" data-id="'+esc(t.id)+'"><span class="pick-check">'+(t.id===w.templateId?'✓':'')+'</span><strong>'+esc(t.title)+'</strong><span>نسخه '+nf(t.version)+' · '+nf(t.stages?.length||0)+' مرحله</span><span>'+esc(t.category)+'</span></button>').join('')+'</div><div class="summary-box"><h4>همراه این قرارداد</h4><p>'+nf(w.services.length)+' سرویس انتخاب‌شده · '+esc(t?.title||'')+' · نسخه '+nf(t?.version)+'</p></div>';
 if(w.step===2)return '<div class="form-grid">'+field('عنوان قرارداد <span class="required">*</span>',input('title',w.title,'required maxlength="250" placeholder="موضوع روشن و مشخص قرارداد"'),true)+field('مشتری هلدینگی <span class="required">*</span>',select('customerId',list('customers').filter(c=>c.status!=='inactive').map(c=>({value:c.id,label:c.name})),w.customerId,'انتخاب مشتری…','required data-wizard-customer'))+field('مدیر حساب',select('managerId',list('managers').filter(m=>m.status!=='inactive').map(m=>({value:m.id,label:m.name})),w.managerId,'تخصیص داده نشده'))+field('نام حقوقی طرف قرارداد <span class="required">*</span>',input('party',w.party,'required maxlength="250"'))+field('واحد بهره‌بردار',input('unit',w.unit,'maxlength="150"'))+field('مالک فرآیند <span class="required">*</span>',input('owner',w.owner,'required maxlength="150"'))+field('مبلغ مبنا (ریال) <span class="required">*</span>',input('amount',w.amount,'type="number" min="0" step="1" required dir="ltr" placeholder="0"'))+field('تاریخ شروع <span class="required">*</span>',input('start',w.start,'type="date" required'))+field('تاریخ پایان <span class="required">*</span>',input('end',w.end,'type="date" required'))+'</div><p class="muted-copy">تاریخ‌ها با تقویم مرورگر وارد و در فهرست به تقویم فارسی نمایش داده می‌شوند.</p>';
 if(w.step===3)return '<div class="section-title-row"><h3 class="section-caption">خدمات و شرایط توافق‌شده</h3><span class="tag blue">'+nf(w.services.length)+' سرویس</span></div><div class="add-service-row">'+select('addService',state.data.catalog.services.filter(s=>!w.services.some(x=>x.code===s.code)).map(s=>({value:s.code,label:s.code+' · '+s.name})),'','افزودن سرویس به قرارداد…','aria-label="سرویس جدید"')+action('wizard-add-service','＋ افزودن')+'</div>'+w.services.map((term,i)=>{const s=getService(term.code);return '<details class="service-terms-card" open><summary><span class="tag blue">'+esc(s.code)+'</span><strong>'+esc(s.name)+'</strong><small>'+esc(s.centerName)+'</small><button type="button" class="table-action danger-text" data-action="wizard-remove-service" data-index="'+i+'" aria-label="حذف '+esc(s.name)+'">×</button></summary><div class="service-terms-body" data-term-index="'+i+'"><div class="form-grid service-terms-grid">'+field('مدل درآمدی',select('revenueModel',Object.entries(modelLabels).map(([value,label])=>({value,label})),term.revenueModel,'انتخاب مدل…','required'))+field('SLA توافق‌شده',select('slaTier',slaProfiles().map(p=>({value:p.code||p.id||p.tier,label:(p.code||p.id||p.tier)+' · '+(p.label||p.name||'')})),term.slaTier,'تعیین نشده','required'))+field('روش ارائه',select('delivery',Object.entries(deliveryLabels).map(([value,label])=>({value,label})),term.delivery,'تعیین نشده','required'))+field('مقدار',input('quantity',term.quantity,'type="number" step="any" min="0.000001" required dir="ltr"'))+field('نرخ واحد (ریال)',input('unitPrice',term.unitPrice,'type="number" step="any" min="0" required dir="ltr" placeholder="نرخ توافق‌شده"'))+'</div><div class="source-terms"><span>منبع: '+esc(s.priceDisplay||s.price?.headlineAmount||s.unit||'نرخ عددی قطعی در داده موجود نیست')+'</span><span>SLA منبع: '+esc(s.tier||'نامشخص')+' · تحویل منبع: '+esc(deliveryLabels[s.delivery]||'نامشخص')+'</span></div></div></details>';}).join('')+(w.services.length?'':'<div class="notice-note">این قرارداد بدون سرویس کاتالوگ تنظیم می‌شود؛ برای قراردادهایی مانند NDA یا اجاره مجاز است.</div>')+'<div class="form-grid terms-editor">'+field('شرایط پرداخت','<textarea name="paymentTerms" rows="3" required>'+esc(w.paymentTerms)+'</textarea>',true)+field('متن پایه قرارداد','<textarea name="body" rows="10" class="contract-editor" required>'+esc(w.body)+'</textarea>',true)+'</div><p class="editor-help">متغیرهای متن هنگام تولید سند توسط سرور تکمیل می‌شوند.</p>';
 if(w.step===4)return '<h3 class="section-caption">فرآیند همین قرارداد</h3><p class="muted-copy">نام، نقش، ترتیب و مهلت را تنظیم کنید. مراحل الزامی و نقش مسئول آن‌ها حفظ می‌شوند؛ مراحل اختیاری قابل افزودن، جابه‌جایی یا حذف‌اند.</p>'+stageEditor(w.stages,'wizard',true);
 const p=w.preview;return '<div class="review-status"><span>✓</span><div><strong>سند از اطلاعات همین قرارداد تولید شد</strong><small>با ثبت، نسخه الگو، مشتری، مدیر حساب، خدمات و مراحل ثابت می‌شوند.</small></div></div><div class="summary-box"><div class="summary-list"><div><span>مشتری</span><b>'+esc(getCustomer(w.customerId)?.name)+'</b></div><div><span>مدیر حساب</span><b>'+esc(getManager(w.managerId)?.name||'بدون تخصیص')+'</b></div><div><span>الگو</span><b>'+esc(t?.title)+' · نسخه '+nf(t?.version)+'</b></div><div><span>مدت</span><b>'+dateText(w.start)+' تا '+dateText(w.end)+'</b></div><div><span>سرویس</span><b>'+nf(w.services.length)+'</b></div><div><span>مبلغ مبنا</span><b>'+nf(w.amount)+' ریال</b></div></div></div><h3 class="section-caption">متن نهایی قرارداد</h3><pre class="document-paper">'+esc(p?.document||'')+'</pre><div class="process-preview">'+w.stages.filter(s=>s.enabled!==false).map((s,i)=>'<span><b>'+nf(i+1)+'</b>'+esc(s.name)+'<small>'+esc(roleName(s.role))+' · '+nf(s.slaDays)+' روز</small></span>').join('')+'</div>';}
function collectWizard(){const w=state.wizard;const form=$('#wizardForm');if(!form)return;const d=new FormData(form);if(w.step===2)for(const key of ['title','customerId','managerId','party','unit','owner','amount','start','end'])w[key]=d.get(key)??w[key];if(w.step===3){w.paymentTerms=d.get('paymentTerms')||'';w.body=d.get('body')||'';$$('[data-term-index]').forEach(row=>{const x=w.services[Number(row.dataset.termIndex)];for(const key of ['revenueModel','slaTier','delivery','quantity','unitPrice'])x[key]=$('[name="'+key+'"]',row).value;});}if(w.step===4)collectStages(w.stages,'wizard');}
async function wizardNext(){if(!$('#wizardForm').reportValidity())return;collectWizard();const w=state.wizard;if(w.step===2){if(!w.title.trim()||!w.party.trim())throw new Error('عنوان و طرف قرارداد را کامل کنید.');if(w.end<w.start)throw new Error('تاریخ پایان باید پس از تاریخ شروع باشد.');}if(w.step===4){validateStages(w.stages);w.preview=await busyRequest(()=>api('/contracts/preview',wizardPayload()));}w.step++;renderWizard();}
async function createContract(){const result=await busyRequest(()=>api('/contracts',wizardPayload()));closeModal();state.selected.clear();persistSelection();state.wizard=null;await refresh(false);navigate('contracts');toast('پیش‌نویس قرارداد ذخیره شد؛ فرآیند را از جزئیات آغاز کنید.');if(result?.id)await showContract(result.id);}


function contractStages(c){return (c.stages||c.snapshot?.stages||[]).filter(s=>s.enabled!==false);}
function completedStage(s){return s.status==='completed'||s.status==='done'||Boolean(s.completedAt);}
function currentStage(c){const rows=contractStages(c);if(c.status==='active')return null;if(c.currentStageId)return rows.find(s=>s.id===c.currentStageId)||rows.find(s=>!completedStage(s));if(Number.isInteger(c.currentStageIndex))return rows[c.currentStageIndex];return rows.find(s=>s.status==='in_progress'||s.status==='active')||rows.find(s=>!completedStage(s));}
async function showContract(id){state.detail=await api('/contracts/'+encodeURIComponent(id));state.detailTab='summary';renderContractDetail();}
function renderContractDetail(){const c=state.detail;const snap=c.snapshot||{};const stages=contractStages(c);const current=currentStage(c);const total=stages.length;const complete=c.status==='active'?total:stages.filter(completedStage).length;const services=snap.services||c.services||[];const tabs=['summary','document','history','snapshot'];const tabNames={summary:'خلاصه و خدمات',document:'سند و الحاقیه‌ها',history:'تاریخچه',snapshot:'نسخه ثابت داده‌ها'};
 let body='<div class="detail-overview"><div><span class="tag blue">'+esc(c.number||c.code||c.id)+'</span>'+chip(c.status)+'</div><p>'+esc(snap.customer?.name||c.party||'')+' · '+dateText(c.createdAt)+'</p><div class="progress"><i style="width:'+(total?100*complete/total:0)+'%"></i></div><small>'+nf(complete)+' از '+nf(total)+' مرحله تکمیل شده</small></div><div class="detail-tabs">'+tabs.map(t=>'<button class="detail-tab '+(state.detailTab===t?'active':'')+'" data-action="detail-tab" data-tab="'+t+'">'+tabNames[t]+'</button>').join('')+'</div>';
 if(state.detailTab==='summary')body+='<div class="detail-columns"><section><div class="meta-grid"><div class="meta-item"><span>مشتری</span><b>'+esc(snap.customer?.name||c.party||'—')+'</b></div><div class="meta-item"><span>مدیر حساب</span><b>'+esc(snap.manager?.name||'تخصیص داده نشده')+'</b></div><div class="meta-item"><span>مبلغ مبنا</span><b>'+nf(c.amount||snap.terms?.amount)+' ریال</b></div><div class="meta-item"><span>الگوی مبنا</span><b>'+esc(snap.template?.title||'—')+' · '+nf(snap.template?.version)+'</b></div><div class="meta-item"><span>شروع</span><b>'+dateText(c.start||snap.terms?.start)+'</b></div><div class="meta-item"><span>پایان</span><b>'+dateText(c.end||snap.terms?.end)+'</b></div></div><h3 class="section-caption">خدمات ثبت‌شده</h3>'+(services.length?services.map(s=>'<div class="snapshot-service"><div><code>'+esc(s.code)+'</code><strong>'+esc(s.name)+'</strong></div><p>'+esc(modelLabels[s.revenueModel||s.model]||s.revenueModel||s.model||'—')+' · '+esc(s.slaTier||s.tier||s.sla?.code||'SLA نامشخص')+' · '+esc(deliveryLabels[s.delivery]||'تحویل نامشخص')+'</p><small>'+esc(s.centerName||'')+' · ثبت منبع '+dateText(s.observedAt||s.capturedAt||snap.capturedAt)+'</small></div>').join(''):empty('بدون سرویس کاتالوگ','موضوع این قرارداد به انتخاب سرویس وابسته نیست.'))+'</section><section class="detail-section"><h3>مراحل قرارداد</h3><div class="contract-stage-list">'+stages.map((s,i)=>'<div class="'+(completedStage(s)||c.status==='active'?'done':s===current&&c.status!=='draft'?'current':'')+'"><span>'+(completedStage(s)||c.status==='active'?'✓':nf(i+1))+'</span><p><strong>'+esc(s.name)+'</strong><small>'+esc(roleName(s.role))+' · '+nf(s.slaDays)+' روز'+(s.required?' · الزامی':'')+'</small>'+(s.completedAt?'<small>'+dateText(s.completedAt)+'</small>':'')+'</p></div>').join('')+'</div></section></div>';
 if(state.detailTab==='document')body+='<div class="document-actions">'+action('download-document','↓ دریافت متن')+action('print-document','چاپ / PDF')+action('new-amendment','＋ الحاقیه','primary')+'</div><pre class="document-paper">'+esc(c.document||snap.document||'سندی موجود نیست.')+'</pre><h3 class="section-caption">الحاقیه‌ها</h3>'+((c.amendments||[]).length?c.amendments.map(a=>'<details class="amendment-card"><summary>'+esc(a.title)+' <small>'+dateText(a.createdAt)+'</small></summary><p class="muted-copy">'+esc(a.reason)+'</p><pre class="document-paper">'+esc(a.body||a.document)+'</pre></details>').join(''):empty('هنوز الحاقیه‌ای ثبت نشده','سند اولیه ثابت می‌ماند؛ تغییرات بعدی به صورت الحاقیه ثبت می‌شوند.'));
 if(state.detailTab==='history')body+='<div class="audit-timeline">'+(c.history||c.events||[]).map(e=>'<article><span>✓</span><div><h4>'+esc(e.title||eventLabels[e.type]||e.message||e.action||e.type||'رویداد')+'</h4><p>'+esc(e.comment||e.description||e.details?.comment||'')+'</p><small>'+dateText(e.createdAt||e.at)+' · '+esc(e.actor||e.role||'پنل دمو')+'</small></div></article>').join('')+'</div>';
 if(state.detailTab==='snapshot')body+='<div class="notice-note">این داده‌ها در زمان ایجاد قرارداد ثبت شده‌اند؛ ویرایش مشتری، الگو یا کاتالوگ آن‌ها را تغییر نمی‌دهد.</div>'+action('download-snapshot','↓ دریافت نسخه JSON')+'<pre class="json-view" dir="ltr">'+esc(JSON.stringify(snap,null,2))+'</pre>';
 showModal(c.title,body,'<div class="page-actions">'+action('contract-neo','اتصال / تلاش مجدد Neo','secondary')+action('print-document','چاپ سند')+'</div>'+(current?action('advance-dialog',c.status==='draft'?'آغاز فرآیند قرارداد ←':'تکمیل «'+esc(current.name)+'» ←','primary'):'<span class="status-chip status-active">فرآیند قرارداد تکمیل شده</span>'),true);
}
function advanceDialog(){const s=currentStage(state.detail);if(!s)return;showModal(state.detail.status==='draft'?'آغاز فرآیند قرارداد':'تکمیل مرحله '+s.name,'<form id="advanceForm">'+field('یادداشت اقدام <span class="required">*</span>','<textarea name="comment" rows="4" required placeholder="نتیجه بررسی و توضیح اقدام"></textarea>')+'<p class="muted-copy">نقش مسئول: '+esc(roleName(s.role))+' · این اقدام در تاریخچه قرارداد ثبت می‌شود.</p></form>',action('detail-back','بازگشت')+action('advance-contract',state.detail.status==='draft'?'ثبت و آغاز فرآیند':'ثبت و تکمیل مرحله','primary'));}
async function advanceContract(){const d=formValues('#advanceForm');if(!d)return;d.expectedStatus=state.detail.status;d.expectedStepId=state.detail.status==='draft'?null:currentStage(state.detail)?.stepId;const wasDraft=state.detail.status==='draft';try{await busyRequest(()=>api('/contracts/'+encodeURIComponent(state.detail.id)+'/advance',d));}catch(error){if(error.status===409){await showContract(state.detail.id);toast('وضعیت قرارداد تغییر کرده بود؛ آخرین وضعیت دریافت شد.','warning');return;}throw error;}const id=state.detail.id;await refresh(false);await showContract(id);renderView();toast(wasDraft?'فرآیند قرارداد آغاز شد.':'مرحله تکمیل و رویداد ثبت شد.');}
function amendmentEditor(){showModal('افزودن الحاقیه','<form id="amendmentForm" class="form-grid">'+field('عنوان الحاقیه <span class="required">*</span>',input('title','','required maxlength="200"'),true)+field('علت تغییر <span class="required">*</span>','<textarea name="reason" rows="2" required></textarea>',true)+field('متن الحاقیه <span class="required">*</span>','<textarea name="body" rows="9" required></textarea>',true)+'</form>',action('detail-back','بازگشت')+action('save-amendment','ثبت الحاقیه','primary'),true);}
async function saveAmendment(){const d=formValues('#amendmentForm');if(!d)return;await busyRequest(()=>api('/contracts/'+encodeURIComponent(state.detail.id)+'/amendments',d));await showContract(state.detail.id);state.detailTab='document';renderContractDetail();await refresh(false);toast('الحاقیه ثبت شد؛ سند اولیه حفظ شده است.');}
function printDocument(){const c=state.detail;const frame=document.createElement('iframe');frame.className='print-frame';frame.title='چاپ قرارداد';frame.srcdoc='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><title>'+esc(c.title)+'</title><style>@page{size:A4;margin:22mm}body{font-family:Tahoma,sans-serif;font-size:12px;line-height:2;color:#182233}h1{font-size:20px}pre{font-family:inherit;white-space:pre-wrap;overflow-wrap:anywhere}.meta{color:#64748b;font-size:10px;border-bottom:1px solid #ddd;padding-bottom:14px;margin-bottom:22px}</style></head><body><h1>'+esc(c.title)+'</h1><div class="meta">'+esc(c.number||c.id)+' · '+dateText(c.createdAt)+'</div><pre>'+esc(c.document||'')+'</pre>'+(c.amendments||[]).map(a=>'<section style="break-before:page"><h2>'+esc(a.title)+'</h2><pre>'+esc(a.body)+'</pre></section>').join('')+'</body></html>';frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000);};document.body.append(frame);}
function settingsView(){const settings=state.data.settings||{};const integrations=state.data.integrations||{};const neo=integrations.neo||{};const sync=integrations.sync||integrations.fanasa||{};const runs=sync.runs||sync.imports||[];return header('تنظیمات و اتصال‌ها','مشخصات فضای کاری، وضعیت زیرساخت و سابقه همگام‌سازی.')+
 '<div class="settings-grid"><section class="card"><div class="card-header"><div><h2>فضای کاری</h2><p>اطلاعات مورد استفاده در پنل</p></div></div><form id="settingsForm" class="card-body"><div class="form-grid">'+field('نام سازمان',input('organizationName',settings.organizationName||'گروه انتخاب','required maxlength="150"'),true)+field('واحد پول','<input value="ریال ایران (IRR)" readonly>')+field('نمایش تاریخ','<input value="شمسی؛ ذخیره‌سازی میلادی" readonly>')+'</div><div class="form-actions">'+action('save-settings','ذخیره تنظیمات','primary')+'</div></form></section>'+
 '<section class="card"><div class="card-header"><div><h2>اتصال Neo</h2><p>ثبت قرارداد و مراحل در پروژه مدیریت کار</p></div>'+chip((neo.connected||neo.status==='connected')?'active':'pending',(neo.connected||neo.status==='connected')?'متصل':neo.status||'نیازمند بررسی')+'</div><div class="card-body"><dl class="integration-meta"><dt>نشانی سرویس</dt><dd dir="ltr">'+esc(neo.baseUrl||neo.url||'تنظیم نشده')+'</dd><dt>پروژه</dt><dd>'+esc(neo.projectName||neo.project?.name||neo.project?.key||neo.projectId||settings.neoProjectId||'تنظیم نشده')+'</dd><dt>آخرین نتیجه</dt><dd>'+esc(neo.message||neo.error||'برای بررسی اتصال اقدام کنید.')+'</dd></dl>'+action('check-neo','بررسی اتصال Neo')+'</div></section></div>'+
 '<section class="card integration-card"><div class="card-header"><div><h2>دریافت کاتالوگ رسمی فن‌آسا</h2><p>URL، زمان، hash و نتیجه دریافت ثبت می‌شود؛ خطا نسخه معتبر قبلی را حذف نمی‌کند.</p></div>'+action('sync-fanasa','↻ دریافت از منبع رسمی','primary')+'</div><div class="card-body">'+sourceBanner()+'<div class="integration-links"><a href="https://fanasa.net/fa/products" target="_blank" rel="noopener">خدمات ↗</a><a href="https://fanasa.net/fa/pricing" target="_blank" rel="noopener">مدل‌های درآمدی ↗</a><a href="https://fanasa.net/fa/pricing/support" target="_blank" rel="noopener">سطح خدمت ↗</a></div><p class="muted-copy">تأیید اپراتور به معنی بازبینی داده دریافت‌شده است. این اقدام، تأیید حقوقی قرارداد یا گواهی مستقل منبع محسوب نمی‌شود.</p>'+(runs.length?'<div class="data-table-wrap"><table class="data-table"><thead><tr><th>زمان دریافت</th><th>نتیجه</th><th>HTTP</th><th>تغییرات</th><th>عملیات</th></tr></thead><tbody>'+runs.map(r=>'<tr><td>'+dateText(r.createdAt||r.observedAt)+'</td><td>'+esc(r.status||r.verificationStatus||'—')+'</td><td>'+esc(r.httpStatus||'—')+'</td><td>'+esc(typeof r.changes==='object'?JSON.stringify(r.changes):r.changeCount??'—')+'</td><td><button class="text-link" data-action="sync-report" data-id="'+esc(r.id)+'">گزارش</button>'+((r.status==='success'||r.status==='imported'||r.status==='pending'||r.verificationStatus==='http-observed-unverified')?'<button class="text-link" data-action="approve-import" data-id="'+esc(r.id)+'">تأیید اپراتور</button>':'')+'</td></tr>').join('')+'</tbody></table></div>':empty('سابقه همگام‌سازی موجود نیست','با دریافت از منبع، اولین گزارش ذخیره می‌شود.'))+'</div></section>';}
function integrationReport(title,result){state.integrationResult=result;const id=result.importId||result.id;showModal(title,'<div class="integration-result"><p>'+esc(result.message||result.summary||'نتیجه عملیات ثبت شد.')+'</p><pre class="json-view" dir="ltr">'+esc(JSON.stringify(result,null,2))+'</pre></div>',action('close-modal','بستن')+(id&&!result.error&&title.includes('کاتالوگ')? action('approve-import','تأیید بازبینی اپراتور','primary','data-id="'+esc(id)+'"') :''),true);}


async function handleAction(a,b){
 const id=b.dataset.id;
 if(a==='new-contract')newWizard();
 else if(a==='catalog-contract')newWizard();
 else if(a==='service-info')serviceInfo(id);
 else if(a==='service-select-toggle'){state.selected.has(id)?state.selected.delete(id):state.selected.add(id);persistSelection();closeModal();renderView();}
 else if(a==='clear-selection'){state.selected.clear();persistSelection();renderView();}
 else if(a==='center-select'){const rows=filteredServices().filter(s=>s.centerId===id);const all=rows.every(s=>state.selected.has(s.code));rows.forEach(s=>all?state.selected.delete(s.code):state.selected.add(s.code));persistSelection();renderView();}
 else if(a==='new-customer'||a==='new-manager')entityEditor(a==='new-customer'?'customer':'manager');
 else if(a==='edit-customer'||a==='edit-manager')entityEditor(a==='edit-customer'?'customer':'manager',id);
 else if(a==='delete-customer'||a==='delete-manager')confirmDelete(a==='delete-customer'?'customer':'manager',id);
 else if(a==='save-entity')await saveEntity();
 else if(a==='confirm-delete')await deleteEntity();
 else if(a==='manager-assign')assignmentEditor(id);
 else if(a==='save-assignment')await saveAssignment();
 else if(a==='new-template')editTemplate();
 else if(a==='edit-template')editTemplate(id);
 else if(a==='save-template')await saveTemplate();
 else if(a==='reload-template'){await refresh(false);editTemplate(id);}
 else if(a==='template-preview')templatePreview(id);
 else if(a==='publish-template'){
  const t=getTemplate(id);
  try{await api('/templates/'+encodeURIComponent(id)+'/publish',{revision:t.revision,templateVersionId:t.templateVersionId});}
  catch(error){if(error.status===409){await refresh();toast('محتوای الگو تغییر کرده است. نسخه تازه را بازبینی کنید و سپس دوباره «انتشار نسخه» را بزنید.','warning');return;}throw error;}
  await refresh();toast('نسخه منتشر شد و آماده ساخت قرارداد است.');
 }
 else if(a==='archive-template'){await api('/templates/'+encodeURIComponent(id)+'/archive',{});await refresh();toast('الگو بایگانی شد.');}
 else if(a==='use-template')newWizard(id,b.dataset.version);
 else if(a==='template-version')templatePreview(id,b.dataset.version);
 else if(a.startsWith('stage-'))manipulateStage(a,b);
 else if(a==='wizard-template'){const t=publishedTemplates().find(x=>x.id===id);state.wizard.templateId=t.id;state.wizard.templateVersionId=t.templateVersionId;state.wizard.body=t.body;state.wizard.stages=clone(t.stages||defaultStages());state.wizard.preview=null;renderWizard();}
 else if(a==='wizard-back'){collectWizard();state.wizard.step--;renderWizard();}
 else if(a==='wizard-next')await wizardNext();
 else if(a==='wizard-create')await createContract();
 else if(a==='wizard-add-service'){collectWizard();const code=$('[name="addService"]').value;if(!code)throw new Error('ابتدا یک سرویس را انتخاب کنید.');if(!state.wizard.services.some(s=>s.code===code))state.wizard.services.push(serviceTerms(getService(code)));renderWizard();}
 else if(a==='wizard-remove-service'){collectWizard();state.wizard.services.splice(Number(b.dataset.index),1);renderWizard();}
 else if(a==='contract-detail')await showContract(id);
 else if(a==='detail-tab'){state.detailTab=b.dataset.tab;renderContractDetail();}
 else if(a==='detail-back')renderContractDetail();
 else if(a==='advance-dialog')advanceDialog();
 else if(a==='advance-contract')await advanceContract();
 else if(a==='new-amendment')amendmentEditor();
 else if(a==='save-amendment')await saveAmendment();
 else if(a==='download-document')download((state.detail.number||state.detail.id)+'.txt',state.detail.document||'');
 else if(a==='download-snapshot')download((state.detail.number||state.detail.id)+'-snapshot.json',JSON.stringify(state.detail.snapshot,null,2),'application/json;charset=utf-8');
 else if(a==='print-document')printDocument();
 else if(a==='contract-neo'){const result=await busyRequest(()=>api('/contracts/'+encodeURIComponent(state.detail.id)+'/neo-sync',{}));await refresh(false);integrationReport('نتیجه اتصال قرارداد به Neo',result);}
 else if(a==='save-settings'){const values=formValues('#settingsForm');if(!values)return;await api('/settings',values,'PUT');await refresh();toast('تنظیمات ذخیره شد.');}
 else if(a==='check-neo'){b.disabled=true;try{const r=await api('/integrations/neo/run',{});await refresh();integrationReport('بررسی اتصال Neo',r);}finally{b.disabled=false;}}
 else if(a==='sync-fanasa'){b.disabled=true;b.textContent='در حال دریافت…';try{const r=await api('/integrations/sync/run',{});await refresh();integrationReport('گزارش دریافت کاتالوگ',r);}finally{b.disabled=false;b.textContent='↻ دریافت از منبع رسمی';}}
 else if(a==='approve-import'){await busyRequest(()=>api('/integrations/sync/approve',{importId:id}));closeModal();await refresh();toast('تأیید اپراتور در گزارش منبع ثبت شد.');}
 else if(a==='sync-report'){const sync=state.data.integrations?.sync||state.data.integrations?.fanasa||{};const report=(sync.runs||sync.imports||[]).find(r=>r.id===id);if(report)integrationReport('جزئیات دریافت منبع',report);}
}
function handleChange(e){
 if(e.target.hasAttribute('data-wizard-version')){const t=(getTemplate(state.wizard.templateId)?.versions||[]).find(v=>v.templateVersionId===e.target.value);if(t){state.wizard.templateVersionId=t.templateVersionId;state.wizard.body=t.body;state.wizard.stages=clone(t.stages);state.wizard.preview=null;renderWizard();}return;}
 if(e.target.dataset.service){const code=e.target.dataset.service;if(e.target.checked)state.selected.add(code);else state.selected.delete(code);persistSelection();renderView();}
 if(e.target.hasAttribute('data-show-archived')){state.showArchived=e.target.checked;renderView();}
 if(e.target.hasAttribute('data-wizard-customer')){collectWizard();const c=getCustomer(e.target.value);if(c){state.wizard.party=c.name;state.wizard.managerId=c.managerId||'';state.wizard.unit=c.unit||'';if(!state.wizard.title.trim())state.wizard.title=wizardTemplate().title+' — '+c.name;renderWizard();}}
}


document.addEventListener('click', async e=>{
 const view=e.target.closest('[data-view]');if(view){if(state.modal)closeModal();navigate(view.dataset.view);return;}
 if(e.target.matches('[data-dismiss]')){closeModal();return;}
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;e.preventDefault();
 try{
 if(a==='close-modal')closeModal();
 else if(a==='refresh')await refresh();
 else if(a==='toggle-sidebar'){$('#sidebar').classList.toggle('open');$('#mobileOverlay').classList.toggle('show');}
 else if(a==='goto-catalog')navigate('catalog');
 else if(a==='export-contracts')exportContracts();
 else if(a==='guide')showModal('راهنمای شروع','<ol class="help-steps"><li>در کاتالوگ، سرویس‌های قرارداد را انتخاب کنید.</li><li>مشتری هلدینگی و مدیر حساب را تعریف کنید.</li><li>یک الگوی منتشرشده انتخاب کرده و شرایط و مراحل را تنظیم کنید.</li><li>سند را بازبینی و قرارداد را ذخیره کنید.</li><li>از جزئیات قرارداد، مراحل را تکمیل و خروجی سند را دریافت کنید.</li></ol>');
 else if(a==='notifications'){navigate('contracts');state.contractFilter='in_process';renderView();}
 else await handleAction(a,b);
 }catch(err){formError(err.message);}
});
document.addEventListener('input', e=>{
 const search=e.target.dataset.search;
 if(search==='contracts'){state.contractSearch=e.target.value;redrawInput(e.target);}
 else if(search==='catalog'){state.catalog.search=e.target.value;redrawInput(e.target);}
 else if(search==='templates'){state.templateSearch=e.target.value;redrawInput(e.target);}
 else if(search==='customers'||search==='managers'){const q=e.target.value.toLowerCase();$$('[data-search-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}
});
function redrawInput(el){const name=el.dataset.search;const start=el.selectionStart;renderView();const next=$('[data-search="'+name+'"]');next?.focus();next?.setSelectionRange(start,start);}
document.addEventListener('change', e=>{if(e.target.dataset.filter){const key=e.target.dataset.filter;if(key==='contractStatus')state.contractFilter=e.target.value;else state.catalog[key]=e.target.value;renderView();}handleChange(e);});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&state.modal){closeModal();return;}
 if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#globalSearch').focus();}
 if(e.key==='Tab'&&state.modal){const els=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]',modalRoot).filter(x=>!x.hidden&&x.offsetParent!==null);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
